/** A search engine that only matches values starting with the term, ignoring case and accents. */
class StartsWithSearchEngine {
    createIndex(items) {
        const values = items.map(String);
        const matches = (value, term) => normalizeSearchText(value).startsWith(normalizeSearchText(term));
        return {
            search: ({ term }) => items.flatMap((item, index) => matches(values[index], term)
                ? [
                    {
                        item,
                        matches: [{ field: 'value', value: values[index], ranges: [[0, term.trim().length]] }],
                    },
                ]
                : []),
            suggest: (term, limit) => values
                .filter((value) => matches(value, term))
                .slice(0, limit)
                .map((value) => ({ value, ranges: [[0, term.trim().length]] })),
        };
    }
}
